begin;
do $$
declare owner_id uuid := gen_random_uuid(); member_id uuid := gen_random_uuid(); outsider_id uuid := gen_random_uuid();
 h1 uuid; h2 uuid; code text; old_code text; a public.inventory; b public.inventory; foreign_item public.inventory;
 session_id uuid := gen_random_uuid(); saved uuid; original_version int; failed boolean; count_before int;
 changes jsonb; result jsonb;
begin
 insert into auth.users(id,email) values(owner_id,owner_id::text || '@tests.invalid'),(member_id,member_id::text || '@tests.invalid'),(outsider_id,outsider_id::text || '@tests.invalid');
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 h1 := (public.mutate('create_household','{"name":"Core tests"}')->>'id')::uuid;
 old_code := public.mutate('invite','{}')->>'code';
 code := public.mutate('invite','{}')->>'code';
 perform set_config('request.jwt.claim.sub',member_id::text,true);
 failed := false;
 begin perform public.mutate('join_household',jsonb_build_object('code',old_code)); exception when sqlstate 'P0001' then failed := true; end;
 assert failed, 'Replaced join code was accepted';
 perform public.mutate('join_household',jsonb_build_object('code',code));
 perform set_config('request.jwt.claim.sub',outsider_id::text,true);
 h2 := (public.mutate('create_household','{"name":"Other test kitchen"}')->>'id')::uuid;
 result := public.mutate('add_item','{"name":"Other rice","quantity":500,"unit":"g","expiry_date":"2099-10-01","category":"Grains","location":"Pantry"}');
 select * into foreign_item from public.inventory where id=(result->>'id')::uuid;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 result := public.mutate('add_item','{"name":"Rice","quantity":500,"unit":"g","expiry_date":"2099-10-01","category":"Grains","location":"Pantry"}');
 select * into a from public.inventory where id=(result->>'id')::uuid;
 result := public.mutate('add_item','{"name":"Eggs","quantity":6,"unit":"piece","expiry_date":"2099-10-10","category":"Protein","location":"Fridge"}');
 select * into b from public.inventory where id=(result->>'id')::uuid;
 assert (select count(*) from public.activity where household_id=h1 and actor_id=owner_id and action='add_item')=2, 'Missing actor/time inventory history';
 assert (select 'Pantry'=any(locations) from public.households where id=h1), 'Storage tag not reusable';
 failed:=false; begin perform public.mutate('add_item','{"name":"Bad precision","quantity":1.234,"unit":"g","expiry_date":"2026-10-01","category":"","location":""}'); exception when others then failed:=true; end; assert failed, 'Three-decimal quantity accepted';
 failed:=false; begin perform public.mutate('add_item','{"name":"Bad null","quantity":null,"unit":"g","expiry_date":"2026-10-01","category":"","location":""}'); exception when others then failed:=true; end; assert failed, 'Null quantity accepted';
 failed:=false; begin perform public.mutate('add_item','{"name":"Bad NaN","quantity":"NaN","unit":"g","expiry_date":"2026-10-01","category":"","location":""}'); exception when others then failed:=true; end; assert failed, 'NaN quantity accepted';
 failed:=false; begin perform public.mutate('adjust_item',jsonb_build_object('id',a.id,'version',a.version,'kind','wrong','amount',1,'discardReason',null)); exception when others then failed:=true; end; assert failed, 'Unknown adjustment kind accepted';
 failed:=false; begin perform public.mutate('adjust_item',jsonb_build_object('id',a.id,'version',a.version,'kind','discarded','amount',1,'discardReason',null)); exception when others then failed:=true; end; assert failed, 'Discard without reason accepted';
 failed:=false; begin perform public.mutate('adjust_item',jsonb_build_object('id',a.id,'version',a.version,'kind','discarded','amount',501,'discardReason','prep')); exception when others then failed:=true; end; assert failed, 'Overdraw adjustment accepted';
 failed:=false; begin perform public.mutate('edit_item',to_jsonb(a)||jsonb_build_object('quantity',1.234,'unit','g')); exception when others then failed:=true; end; assert failed, 'Three-decimal edit accepted';
 failed:=false; begin perform public.mutate('edit_item',to_jsonb(a)||jsonb_build_object('quantity','NaN','unit','g')); exception when others then failed:=true; end; assert failed, 'NaN edit accepted';
 failed:=false; begin perform public.mutate('adjust_item',jsonb_build_object('id',a.id,'version',a.version,'kind','restock','amount',1.234,'discardReason',null)); exception when others then failed:=true; end; assert failed, 'Three-decimal adjustment accepted';
 failed:=false; begin perform public.mutate('edit_item',to_jsonb(a)||jsonb_build_object('quantity',400,'unit','ml')); exception when others then failed:=true; end; assert failed, 'Unit mutation accepted';

 -- Exercise actual authenticated read permissions, not superuser-only filtering.
 perform set_config('role','authenticated',true);
 assert (select count(*) from public.households)=1, 'Household RLS leak';
 assert (select count(*) from public.inventory)=2, 'Inventory RLS leak';
 assert (select count(*) from public.inventory where id=foreign_item.id)=0, 'Foreign item visible';
 failed:=false;
 begin perform public.mutate('edit_item',to_jsonb(foreign_item)); exception when sqlstate 'PT409' then failed:=true; end;
 assert failed, 'Foreign item editable';
 failed:=false;
 begin update public.inventory set stock=5 where id=a.id; exception when insufficient_privilege then failed:=true; end;
 assert failed, 'Direct inventory writes bypass RPC';
 perform set_config('role','postgres',true);

 changes:=jsonb_build_array(jsonb_build_object('id',a.id,'version',a.version,'usedAmount',100,'discardedAmount',0,'discardReason',null),jsonb_build_object('id',b.id,'version',b.version+1,'usedAmount',1,'discardedAmount',0,'discardReason',null));
 count_before:=(select count(*) from public.outcomes where household_id=h1);
 failed:=false;
 begin perform public.confirm_meal(owner_id,h1,session_id,jsonb_build_object('name','Rice meal','ingredients',jsonb_build_array(jsonb_build_object('ingredientId',a.id,'amount',100,'unit','g'),jsonb_build_object('ingredientId',b.id,'amount',1,'unit','piece'))),changes); exception when sqlstate 'PT409' then failed:=true; end;
 assert failed, 'Stale confirmation accepted';
 assert (select version from public.inventory where id=a.id)=a.version, 'Failed confirmation partially updated stock';
 assert (select count(*) from public.outcomes where household_id=h1)=count_before, 'Failed confirmation stored an outcome';
 changes:=jsonb_build_array(jsonb_build_object('id',a.id,'version',a.version,'usedAmount',100,'discardedAmount',0,'discardReason',null),jsonb_build_object('id',b.id,'version',b.version,'usedAmount',1,'discardedAmount',1,'discardReason','prep'));
 saved:=public.confirm_meal(owner_id,h1,session_id,jsonb_build_object('name','Rice meal','ingredients',jsonb_build_array(jsonb_build_object('ingredientId',a.id,'amount',100,'unit','g'),jsonb_build_object('ingredientId',b.id,'amount',1,'unit','piece'))),changes);
 assert saved=public.confirm_meal(owner_id,h1,session_id,jsonb_build_object('name','Rice meal','ingredients',jsonb_build_array(jsonb_build_object('ingredientId',a.id,'amount',100,'unit','g'),jsonb_build_object('ingredientId',b.id,'amount',1,'unit','piece'))),changes), 'Duplicate confirmation not idempotent';
 assert (select count(*) from public.outcomes where household_id=h1)=count_before+1, 'Duplicate outcome stored';
 assert (select quantity from public.inventory where id=a.id)=400, 'Remaining quantity not saved';
 assert (select quantity from public.inventory where id=b.id)=4, 'Discarded quantity not saved';
 assert (select exists(select 1 from jsonb_array_elements(ingredients) x where x->>'name'='Eggs') from public.outcomes where id=saved), 'Historical name snapshot missing';
 assert (select exists(select 1 from jsonb_array_elements(ingredients) x where x->>'id'=a.id::text and x->>'expiry_date'='2099-10-01') from public.outcomes where id=saved), 'Historical expiry snapshot missing';
 assert (select exists(select 1 from jsonb_array_elements(ingredients) x where x->>'name'='Eggs' and (x->>'used')::boolean and (x->>'discarded')::boolean) from public.outcomes where id=saved), 'Use/discard flags conflated';
 failed:=false;
 begin perform public.confirm_meal(outsider_id,h1,gen_random_uuid(),jsonb_build_object('name','Rice meal','ingredients',jsonb_build_array(jsonb_build_object('ingredientId',a.id,'amount',100,'unit','g'),jsonb_build_object('ingredientId',b.id,'amount',1,'unit','piece'))),changes); exception when insufficient_privilege then failed:=true; end;
 assert failed, 'Outsider confirmation accepted';
 failed:=false;
 begin perform public.confirm_meal(owner_id,h1,session_id,jsonb_build_object('name','Different meal','ingredients',jsonb_build_array(jsonb_build_object('ingredientId',a.id,'amount',100,'unit','g'),jsonb_build_object('ingredientId',b.id,'amount',1,'unit','piece'))),changes); exception when sqlstate 'PT409' then failed:=true; end;
 assert failed, 'Changed recipe reused confirmed session';
 assert not has_function_privilege('authenticated','public.confirm_meal(uuid,uuid,uuid,jsonb,jsonb)','execute'), 'Client can forge a confirmed recipe';

 -- Stale single-item edits and undo must not overwrite a later cooking write.
 failed:=false;
 begin perform public.mutate('edit_item',to_jsonb(b)); exception when sqlstate 'PT409' then failed:=true; end;
 assert failed, 'Stale edit accepted';
 failed:=false;
 begin perform public.mutate('undo','{}'); exception when sqlstate 'PT409' then failed:=true; end;
 assert failed, 'Undo overwrote cooking confirmation';
 select * into a from public.inventory where id=a.id;
 perform public.mutate('remove_item',jsonb_build_object('id',a.id,'version',a.version));
 perform public.mutate('undo','{}');
 assert not (select deleted from public.inventory where id=a.id), 'Safe removal undo failed';
 select * into a from public.inventory where id=a.id;
 count_before:=(select count(*) from public.quantity_events where item_id=a.id and not voided);
 perform public.mutate('edit_item',to_jsonb(a)||jsonb_build_object('name','Rice renamed','quantity',400,'unit','g','expiry_date','2099-11-01'));
 assert (select exists(select 1 from jsonb_array_elements(ingredients) x where x->>'id'=a.id::text and x->>'expiry_date'='2099-10-01') from public.outcomes where id=saved), 'Inventory edit changed historical expiry';
 assert (select count(*) from public.quantity_events where item_id=a.id and not voided)=count_before, 'Metadata edit created quantity event';
 select * into a from public.inventory where id=a.id;
 perform public.mutate('adjust_item',jsonb_build_object('id',a.id,'version',a.version,'kind','restock','amount',50,'discardReason',null));
 select * into a from public.inventory where id=a.id;
 perform public.mutate('undo','{}');
 assert (select quantity from public.inventory where id=a.id)=400, 'Restock undo did not restore quantity';
 assert (select count(*) from public.quantity_events where item_id=a.id and voided)=1, 'Restock event was not voided';
 select * into a from public.inventory where id=a.id;
 perform public.mutate('adjust_item',jsonb_build_object('id',a.id,'version',a.version,'kind','discarded','amount',25,'discardReason','prep'));
 select * into a from public.inventory where id=a.id;
 perform public.mutate('undo','{}');
 assert (select quantity from public.inventory where id=a.id)=400, 'Waste undo did not restore quantity';
 assert (select count(*) from public.quantity_events where item_id=a.id and voided)=2, 'Waste event was not voided';
 select * into a from public.inventory where id=a.id;
 update public.inventory set quantity=null,unit=null,stock=0,version=version+1 where id=a.id;
 select * into a from public.inventory where id=a.id;
 perform public.mutate('edit_item',to_jsonb(a)||jsonb_build_object('quantity',200,'unit','g'));
 select * into a from public.inventory where id=a.id;
 perform public.mutate('undo','{}');
 assert (select quantity is null and unit is null from public.inventory where id=a.id), 'Legacy null quantity undo did not restore pair';

 original_version:=(select version from public.households where id=h1);
 failed:=false;
 begin perform public.mutate('leave',jsonb_build_object('version',original_version)); exception when sqlstate 'P0001' then failed:=true; end;
 assert failed, 'Owner left an ownerless household';
 perform set_config('request.jwt.claim.sub',member_id::text,true);
 failed:=false;
 begin perform public.mutate('transfer',jsonb_build_object('version',original_version,'user_id',owner_id)); exception when insufficient_privilege then failed:=true; end;
 assert failed, 'Member can transfer ownership';
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 failed:=false;
 begin perform public.mutate('transfer',jsonb_build_object('version',original_version-1,'user_id',member_id)); exception when sqlstate 'PT409' then failed:=true; end;
 assert failed, 'Stale ownership change accepted';
 perform public.mutate('transfer',jsonb_build_object('version',original_version,'user_id',member_id));
 assert (select hh.owner_id from public.households hh where id=h1)=member_id, 'Ownership transfer failed';
 perform set_config('request.jwt.claim.sub',member_id::text,true);
 perform public.mutate('remove_member',jsonb_build_object('version',original_version+1,'user_id',owner_id));
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 perform set_config('role','authenticated',true);
 assert (select count(*) from public.inventory)=0 and (select count(*) from public.outcomes)=0, 'Removed member retains access';
 perform set_config('role','postgres',true);
 perform set_config('request.jwt.claim.sub',member_id::text,true);
 failed:=false;
 begin perform public.mutate('delete_household',jsonb_build_object('version',original_version+2,'confirmation','Wrong name')); exception when sqlstate 'P0001' then failed:=true; end;
 assert failed, 'Deletion confirmation bypassed';
 perform public.mutate('delete_household',jsonb_build_object('version',original_version+2,'confirmation','Core tests'));
 assert not exists(select 1 from public.inventory where household_id=h1), 'Deleted household retained inventory';
 assert not exists(select 1 from public.outcomes where household_id=h1), 'Deleted household retained outcomes';
 assert not exists(select 1 from public.memberships where household_id=h1), 'Deleted household retained membership';
 raise notice 'PASS: core CRUD/undo, history, RLS, confirmation atomicity/idempotency, flags, snapshots, permissions, membership/version/deletion rules';
end $$;
rollback;
